        {'id': 'Q85', 'objective': 'Objective 2', 'difficulty': 'hard', 'topic': 'Azure AI Vision vs Document Intelligence', 'type': 'dropdown-hotspot', 'scenario': 'Identify the appropriate Azure Cognitive Service for each retail task.', 'question': 'Select the correct service option.', 'correct_answer': ['Azure AI Vision', 'Azure AI Document Intelligence'], 'explanations': {'correct': 'Azure AI Vision is designed for image classification and object detection (like identifying safety helmets). Azure AI Document Intelligence is optimized for extracting structured text, layout, and key-value fields from forms and purchase orders.', 'incorrect': 'Document Intelligence processes document layout elements rather than general visual objects in photos.', 'concept': 'Azure AI Vision vs Document Intelligence workloads.'}, 'avg_time': 55, 'confused_services': ['vision', 'doc-intel'], 'parts': [{'text': 'To identify if customers are wearing safety helmets in a warehouse photo, use ', 'options': ['Azure AI Vision', 'Azure AI Document Intelligence', 'Azure OpenAI'], 'answer': 'Azure AI Vision'}, {'text': '. To extract item prices and vendor addresses from purchase orders, use ', 'options': ['Azure AI Vision', 'Azure AI Document Intelligence', 'Azure AI Language'], 'answer': 'Azure AI Document Intelligence'}]},
        {'id': 'Q86', 'objective': 'Objective 2', 'difficulty': 'hard', 'topic': 'Azure AI Vision: OCR vs Object detection', 'type': 'single-choice', 'scenario': 'You are designing an AI pipeline for an automated recycling plant. You need to: (1) Detect plastic bottles on a conveyor, (2) Read serial numbers on metal cans, and (3) Identify brand labels on boxes.', 'question': 'What combination of capabilities should you implement?', 'correct_answer': 'Object Detection (for bottles), OCR (for serial numbers), and Image Analysis (for brands)', 'explanations': {'correct': 'Detecting bottles is Object Detection. Reading serials is OCR. Identifying brands is Image Analysis/tagging.', 'incorrect': 'Document Intelligence is for document forms, not physical object recycling on conveyor belts. Face API targets faces. Spatial analysis tracks movement vectors, not object features.', 'concept': 'Component selection in vision pipelines.'}, 'avg_time': 65, 'confused_services': ['vision', 'ocr'], 'options': ['Object Detection (for bottles), OCR (for serial numbers), and Image Analysis (for brands)', 'Document Intelligence Layout model for all tasks', 'Face API for brand analysis', 'Spatial Analysis for conveyor belt timing']},
        {'id': 'Q87', 'objective': 'Objective 2', 'difficulty': 'medium', 'topic': 'Azure AI Vision: True/False Matrix', 'type': 'true-false-matrix', 'scenario': 'For each of the following statements about Azure AI Vision and Document Intelligence, select Yes if the statement is true. Otherwise, select No.', 'question': 'Select the correct option for each statement.', 'correct_answer': ['Yes', 'Yes', 'No'], 'explanations': {'correct': 'The Face API handles identity verification. Document Intelligence Layout extracts tables. OCR in Azure AI Vision is capable of extracting both printed and handwritten text.', 'incorrect': 'Review vision capabilities: Face API supports face identification, and OCR supports print and handwriting extraction.', 'concept': 'Azure vision and document services.'}, 'avg_time': 50, 'confused_services': ['face', 'layout-model', 'ocr'], 'statements': [{'text': 'The Face API can be configured to perform face matching against a secure database of employee cards.', 'answer': 'Yes'}, {'text': 'Azure AI Document Intelligence Layout model can extract structured tables.', 'answer': 'Yes'}, {'text': 'OCR in Azure AI Vision is incapable of detecting handwritten text.', 'answer': 'No'}]},
        {'id': 'Q88', 'objective': 'Objective 2', 'difficulty': 'medium', 'topic': 'Azure AI Vision: Matching', 'type': 'drag-drop', 'scenario': 'Match each business challenge to the correct Azure AI Vision or Document Intelligence feature.', 'question': 'Match the challenge with the feature.', 'correct_answer': ['OCR', 'Prebuilt ID model', 'Spatial Analysis'], 'explanations': {'correct': 'OCR extracts raw text characters from street sign images. The Prebuilt ID model parses specific layout fields (like name) from drivers licenses. Spatial Analysis measures movement and crowd queue dwell times.', 'incorrect': 'Do not confuse raw character recognition with spatial flow tracking or prebuilt document parsing.', 'concept': 'Azure AI Vision capabilities.'}, 'avg_time': 45, 'confused_services': ['ocr', 'spatial-analysis', 'doc-intel'], 'draggableItems': ['Spatial Analysis', 'Prebuilt ID model', 'OCR'], 'targets': [{'label': 'Extracting text letters from scanned photos of street signs.', 'answer': 'OCR'}, {'label': "Extracting customer name from a driver's license image.", 'answer': 'Prebuilt ID model'}, {'label': 'Measuring crowd queues inside a train platform.', 'answer': 'Spatial Analysis'}]},
        {'id': 'Q89', 'objective': 'Objective 2', 'difficulty': 'easy', 'topic': 'Azure AI Vision: Face API basics', 'type': 'single-choice', 'scenario': 'A software engineer is deploying the Face API. They need to understand what coordinates the API returns when a face is detected in a photo.', 'question': 'What does the API return to indicate face position?', 'correct_answer': 'A pixel bounding box coordinates', 'explanations': {'correct': 'Face API returns a face rectangle coordinates bounding box (top, left, width, height) indicating face position.', 'incorrect': 'It does not return GPS coordinates, index IDs, or full 3D head meshes natively by default.', 'concept': 'Facial coordinates bounding boxes.'}, 'avg_time': 30, 'confused_services': ['face', 'spatial-analysis'], 'options': ['A pixel bounding box coordinates', 'A 3D coordinate mesh map of the head', 'The latitude/longitude of the photo', 'An index lookup ID']},
