        {'id': 'Q100', 'objective': 'Objective 2', 'difficulty': 'medium', 'topic': 'Azure AI Language: True/False Matrix', 'type': 'true-false-matrix', 'scenario': 'For each of the following statements about Azure AI Language and Speech services, select Yes if the statement is true. Otherwise, select No.', 'question': 'Select the correct option for each statement.', 'correct_answer': ['Yes', 'No', 'Yes'], 'explanations': {'correct': 'PII Detection identifies and redacts credit cards and other sensitive values. Speech Translation handles spoken language translation directly. CLU is designed for dialogue intent extraction, not audio translation.', 'incorrect': 'CLU acts on text inputs for intent and entity mapping; it does not translate audio streams.', 'concept': 'Speech translation and Language services.'}, 'avg_time': 50, 'confused_services': ['pii', 'clu', 'speech-translation'], 'statements': [{'text': 'PII Detection can detect credit card numbers in text documents.', 'answer': 'Yes'}, {'text': 'Conversational Language Understanding (CLU) handles audio translation directly.', 'answer': 'No'}, {'text': 'Speech Translation can translate spoken audio to synthesized speech in another language.', 'answer': 'Yes'}]},
        {'id': 'Q101', 'objective': 'Objective 2', 'difficulty': 'easy', 'topic': 'RAG: Search Indexing', 'type': 'single-choice', 'scenario': 'You are building a RAG search agent. You need to store the vector embeddings representing your product manuals in a searchable repository.', 'question': 'Which Azure component acts as this vector and metadata repository?', 'correct_answer': 'Azure AI Search Index', 'explanations': {'correct': 'The Search Index in Azure AI Search holds vector representations and text fields to support similarity matching.', 'incorrect': 'Model catalog stores models. Compute nodes provide processing power. Storage queues handle message queues.', 'concept': 'Search indices act as vector stores in RAG.'}, 'avg_time': 40, 'confused_services': ['search-index', 'model-deployment'], 'options': ['Azure AI Search Index', 'Azure OpenAI model catalog', 'Azure AI Hub compute node', 'Azure Storage Queue']},
