        {'id': 'Q108', 'objective': 'Objective 2', 'difficulty': 'medium', 'topic': 'Responsible AI: RAG Groundedness evaluation', 'type': 'single-choice', 'scenario': "You deploy a RAG search tool for technical manuals. You want to measure if the model's generated text response is strictly grounded in the retrieved manuals rather than containing hallucinations.", 'question': 'Which evaluation metric in Azure AI Foundry should you monitor?', 'correct_answer': 'Groundedness', 'explanations': {'correct': "Groundedness evaluates if the model's claims are mathematically sourced from the retrieved context blocks.", 'incorrect': 'Coherence checks sentence flow. Fluency evaluates grammar. Relevance evaluates if it answers the query.', 'concept': 'Groundedness measures factual alignment in RAG systems.'}, 'avg_time': 50, 'confused_services': ['groundedness', 'relevance'], 'options': ['Coherence', 'Groundedness', 'Fluency', 'Relevance']},
        {'id': 'Q109', 'objective': 'Objective 2', 'difficulty': 'hard', 'topic': 'Conversational AI: AI Agents', 'type': 'single-choice', 'scenario': 'You want to design a vacation helper. Instead of just chatting, the assistant must check flight seats via API, confirm booking statuses, and send notifications to users.', 'question': 'Which generative AI architecture does this reflect?', 'correct_answer': 'An AI Agent (with tool calling)', 'explanations': {'correct': 'AI Agents use LLMs to select and invoke external tools (APIs, DBs) to accomplish tasks dynamically.', 'incorrect': 'Chatbots only output text. Embeddings build vector coordinate points. Blocklists manage safety filters.', 'concept': 'AI Agents employ tools to run operations.'}, 'avg_time': 60, 'confused_services': ['chatbot', 'agent'], 'options': ['A stateless chatbot', 'An AI Agent (with tool calling)', 'A vector embeddings builder', 'A content filter blocklist']},
